                    await JsUntil(reopened.HtmlSurface, "document.querySelector('#history-list').textContent.includes('Today')&&!!document.querySelector('#history-list .outcome-completed')");
                    Check(await reopened.HtmlSurface.EvaluateAsync("document.querySelector('#history-list').dataset.density==='compact'") == "true", "History density did not survive other settings saves and reopening.");
                    Check(await reopened.HtmlSurface.EvaluateAsync($"document.querySelector('#history-list [data-id=\"{complete.Snapshot.Id}\"] .history-ended').textContent===new Date({JsonSerializer.Serialize(historicalEnd)}).toLocaleDateString(undefined,{{month:'short',day:'numeric'}})&&document.querySelector('#history-list').textContent.includes('Unknown date')") == "true", "Older history must show a date, and records without an end date must remain explicit.");
                    await reopened.HtmlSurface.EvaluateAsync($"document.querySelector('#history-list [data-id=\"{failedReply.TaskId}\"] .history-filename').click()");
                    await JsUntil(reopened.HtmlSurface,"document.querySelector('#history-details')?.textContent.includes('Date unavailable')");
                    await reopened.HtmlSurface.EvaluateAsync("document.querySelector('[aria-label=\"Close download details\"]').click()");
                    await reopened.HtmlSurface.CaptureAsync(Path.Combine(output,"history-dates.png"));
                    Check(await reopened.HtmlSurface.EvaluateAsync($"document.querySelector('#history-list [data-id=\"{zeroProgressId}\"] [role=progressbar]').getAttribute('aria-valuenow')==='0.0'&&document.querySelector('#history-list [data-id=\"{zeroProgressId}\"] .history-progress>div').style.width==='0%'") == "true", "Zero-byte cancelled records must display an empty track.");
                    await Fill(reopened.HtmlSurface,"history-sort","date-asc","change");
                    Check(await reopened.HtmlSurface.EvaluateAsync("[...document.querySelectorAll('#history-list .history-row')].at(-1).querySelector('.history-ended').textContent==='Unknown'") == "true", "Oldest-first sorting placed unknown dates before known dates.");
                    var largestHistoryId = rows.Items.Cast<DownloadRow>().Where(r=>r.State is DownloadState.Completed or DownloadState.Cancelled or DownloadState.Failed).OrderByDescending(r=>r.Snapshot.Received).First().Snapshot.Id;
                    await Fill(reopened.HtmlSurface,"history-sort","size","change");
                    Check(await reopened.HtmlSurface.EvaluateAsync($"document.querySelector('#history-list .history-row').dataset.id==='{largestHistoryId}'") == "true", "Downloaded-size sorting used advertised size instead of received bytes.");
                    await Fill(reopened.HtmlSurface,"type","Video","change");
                    Check(await reopened.HtmlSurface.EvaluateAsync("document.querySelectorAll('.history-file-icon .icon-tabler-video').length===4") == "true", "Video records use missing or generic icons.");
                    await reopened.HtmlSurface.EvaluateAsync("document.querySelector('.history-row').click()");
                    await JsUntil(reopened.HtmlSurface,"document.querySelector('#history-inspector').textContent.includes('Category: http-403')");
                    Check(await reopened.HtmlSurface.EvaluateAsync("document.querySelector('#history-pane-toggle').getAttribute('aria-pressed')==='true'&&document.querySelector('#history-pane-toggle svg')!==null&&document.querySelector('#history-inspector').textContent.includes('Failure reason')") == "true", "Failure diagnostics or accessible icon toggle is missing.");
                    await reopened.HtmlSurface.CaptureAsync(Path.Combine(output,"history-failure-diagnostics.png"));
                    await reopened.HtmlSurface.EvaluateAsync("[...document.querySelectorAll('.history-pane-actions button')].find(e=>e.textContent==='Verify & troubleshoot').click()");
                    await JsUntil(reopened.HtmlSurface,"document.querySelector('#history-details')?.textContent.includes('Category: http-403')");
                    Check(await reopened.HtmlSurface.EvaluateAsync("!!document.querySelector('.details-failure')&&!document.querySelector('#verify-file')&&!document.querySelector('#history-checksum')&&!document.querySelector('#download-integrity').open&&document.querySelector('#download-technical-details').open") == "true", "Failed details show irrelevant verification controls or expanded secondary diagnostics.");
                    Check(await reopened.HtmlSurface.EvaluateAsync("(()=>{const p=document.querySelector('.download-details').getBoundingClientRect(),h=document.querySelector('.details-header').getBoundingClientRect(),f=document.querySelector('.details-footer').getBoundingClientRect();return p.height<=innerHeight*.85+1&&h.top>=p.top&&f.bottom<=p.bottom+1&&document.querySelector('#details-retry').textContent==='Retry download';})()") == "true", "Details sizing, pinned header/footer, or retry terminology is incorrect.");
                    await reopened.HtmlSurface.CaptureAsync(Path.Combine(output,"download-details-failed.png"));
                    await reopened.HtmlSurface.EvaluateAsync("document.querySelector('#download-technical-details').open=true;document.querySelector('.details-scroll').scrollTop=99999");
                    Check(await reopened.HtmlSurface.EvaluateAsync("(()=>{const p=document.querySelector('.download-details').getBoundingClientRect(),f=document.querySelector('.details-footer').getBoundingClientRect();return f.bottom<=p.bottom+1&&document.querySelector('.details-header').getBoundingClientRect().top>=p.top;})()") == "true", "Scrolling diagnostics displaced the dialog header or footer.");
                    await reopened.HtmlSurface.EvaluateAsync("document.querySelector('[aria-label=\"Close download details\"]').click()");
                    await reopened.HtmlSurface.EvaluateAsync("document.querySelector('[aria-label=Settings]').click()");
                    await JsUntil(reopened.HtmlSurface,"!!document.querySelector('#settings-folder')");
                    await reopened.HtmlSurface.EvaluateAsync("[...document.querySelectorAll('[role=button]')].find(e=>e.textContent.trim()==='Appearance').click()");
                    await JsUntil(reopened.HtmlSurface,"!!document.querySelector('[aria-label=\"Group repeated attempts\"]')");
                    await reopened.HtmlSurface.EvaluateAsync("document.querySelector('[aria-label=\"Group repeated attempts\"]').click()");
                    await Until(()=>File.ReadAllText(Path.Combine(directory,"download-preferences.json")).Contains("\"HistoryGroupAttempts\":true"));
                    await reopened.HtmlSurface.EvaluateAsync("document.querySelector('[aria-label=History]').click()");
                    await JsUntil(reopened.HtmlSurface,"!!document.querySelector('.history-attempt-group')");
                    await Fill(reopened.HtmlSurface,"type","Video","change");
                    Check(await reopened.HtmlSurface.EvaluateAsync("document.querySelectorAll('.history-attempt-group').length===1&&document.querySelector('.history-attempt-group').textContent.includes('2 attempts')&&document.querySelectorAll('.history-row').length===2") == "true", "Attempt grouping merged different URLs or output qualities.");
                    await reopened.HtmlSurface.EvaluateAsync("document.querySelector('.history-attempt-group').click()");
                    Check(await reopened.HtmlSurface.EvaluateAsync("document.querySelector('.history-attempt-group').getAttribute('aria-expanded')==='true'&&document.querySelectorAll('.history-row').length===4") == "true", "Expanding attempts did not restore individual record actions.");
                    await reopened.HtmlSurface.CaptureAsync(Path.Combine(output,"history-grouped-attempts.png"));
                    await reopened.HtmlSurface.EvaluateAsync("document.querySelector('#clear-downloads').click()");
                    await JsUntil(reopened.HtmlSurface,"!!document.querySelector('#clear-downloads-dialog')");
                    Check(await reopened.HtmlSurface.EvaluateAsync("document.querySelector('input[name=clear-history-mode]:checked').value==='completed'")=="true","Clear mode should default to completed only.");
                    await reopened.HtmlSurface.EvaluateAsync("document.querySelector('input[value=custom]').click()");
                    await JsUntil(reopened.HtmlSurface,"!document.querySelector('#clear-custom-list').hidden&&document.querySelector('#confirm-clear-downloads').disabled");
                    await reopened.HtmlSurface.CaptureAsync(Path.Combine(output,"clear-downloads.png"));
                    await reopened.HtmlSurface.EvaluateAsync("document.querySelector('#clear-downloads-dialog').dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',bubbles:true}))");
                    await JsUntil(reopened.HtmlSurface,"!document.querySelector('#clear-downloads-dialog')");
                    await reopened.HtmlSurface.EvaluateAsync("document.querySelector('#clear-downloads').click();document.querySelector('input[value=all]').click();document.querySelector('#confirm-clear-downloads').click()");
                    await JsUntil(reopened.HtmlSurface,"!document.querySelector('#clear-downloads-dialog')&&document.querySelector('#history-records').textContent==='0'");
                    Check(File.Exists(complete.Snapshot.Destination),"Clear history deleted a completed file.");
                } finally { reopened.Close(); await Until(() => !reopened.IsVisible); }
                await using (var accounting = await Syphon.Engine.DownloadCoordinator.OpenAsync(Path.Combine(directory,"byte-accounting"))) {
                    const long length = 8388608; var saved = Path.Combine(directory,"resumed-bytes.bin");
                    var record = accounting.Add(new Uri(fixture.BaseAddress,$"resume?size={length}"),saved,singleConnection:true);accounting.Resume(record.Id);
                    await Until(()=>accounting.Get(record.Id).Received>=131072);await accounting.PauseAsync(record.Id,true);
                    var partial=accounting.Get(record.Id);Check(partial.Received==partial.Committed&&partial.Received>0&&partial.Received<length,"Cancelled history must report saved bytes, not the advertised total.");
                    accounting.Resume(record.Id);accounting.Resume(record.Id);await accounting.WaitForIdleAsync(record.Id);
                    var result=accounting.Get(record.Id);Check(result.State==DownloadState.Completed&&result.Received==length&&result.Committed==length&&new FileInfo(saved).Length==length,"Resume counted the same bytes more than once.");
                    Check(result.Sha256==Payload.ExpectedHash(length),"Resumed file bytes differ from the fixture.");
                }
                await DetailsSmokeTests.RunAsync(output);
                Console.WriteLine("PASS HTML desktop: custom chrome minimize/maximize/restore/close, native drag regions and resize frame, manual/browser options, validation, queue, card pause/resume/cancel, floating controls, persisted settings, history and verified bytes; details setup guidance, prerequisite gating and recheck/retry."); code = 0;
            } catch (Exception ex) { Console.Error.WriteLine(ex); if(window.HtmlSurface?.IsReady==true) { Console.Error.WriteLine(await window.HtmlSurface.EvaluateAsync("window.__syphonError || document.body.innerText")); await window.HtmlSurface.CaptureAsync(Path.Combine(output, "failure.png")); } }
            finally { if(window.IsVisible){window.Close();await Until(()=>!window.IsVisible);} app.Shutdown(code); }
        };
        app.Run(window); return code;
    }
    private sealed class FloatingProbe(FloatingDownloadWindow window)
    {
        private Microsoft.Web.WebView2.Wpf.IWebView2 View => ((Grid)window.Content).Children.OfType<Microsoft.Web.WebView2.Wpf.IWebView2>().Single();
        public bool Ready => View.CoreWebView2 is not null;
        public Task<string> EvaluateAsync(string script) => View.CoreWebView2.ExecuteScriptAsync(script);
        public async Task CaptureAsync(string path) { await using var output = File.Create(path); await View.CoreWebView2.CapturePreviewAsync(Microsoft.Web.WebView2.Core.CoreWebView2CapturePreviewImageFormat.Png, output); }
    }
    private static Task Ready(FloatingProbe ui) => Until(() => ui.Ready);
    private static async Task CheckNeuro(LocalHtmlSurface ui)
    {
        Check(await ui.EvaluateAsync("(()=>{const css=getComputedStyle(document.documentElement);const l=key=>{const hex=css.getPropertyValue(key).trim().slice(1);return [.2126,.7152,.0722].reduce((sum,w,i)=>{const s=parseInt(hex.slice(i*2,i*2+2),16)/255;return sum+w*(s<=.04045?s/12.92:((s+.055)/1.055)**2.4);},0);};return ['--sub','--muted'].every(fg=>['--bg','--surface','--raised','--inset'].every(bg=>(l(fg)+.05)/(l(bg)+.05)>=4.5));})()") == "true", "Secondary text contrast falls below 4.5:1.");
        Check(await ui.EvaluateAsync("[['--bg','#070709'],['--surface','#08080b'],['--raised','#14111d'],['--inset','#08080b'],['--accent','#a791ff'],['--accent-dim','#7250ba'],['--bright','#eeeef4'],['--sub','#b2afbf'],['--muted','#9c95ad'],['--text','#eeeef4'],['--accent-text','#baa2f0'],['--emphasis','#f0eaf8'],['--ls','rgba(255,255,255,0.0225)'],['--ds','rgba(0,0,0,0.65)'],['--success','#4a9e6a'],['--warning','#b87a2a'],['--danger','#9e4a4a']].every(([key,value])=>getComputedStyle(document.documentElement).getPropertyValue(key).trim().toLowerCase()===value)") == "true", "Neuro palette differs between pages.");
        Check(await ui.EvaluateAsync("!document.querySelector('[class*=tex-],[class*=sh-]')&&!document.querySelector('#reference-style').textContent.includes('--tex:')") == "true", "Legacy texture or shadow classes remain.");
    }
    private static async Task JsUntil(FloatingProbe ui, string predicate) { var end = DateTime.UtcNow.AddSeconds(30); while (await ui.EvaluateAsync(predicate) != "true") { if (DateTime.UtcNow > end) throw new TimeoutException("Floating UI condition: " + predicate); await Task.Delay(50); } }
    private static async Task OpenAppearance(LocalHtmlSurface ui) {
        await ui.EvaluateAsync("document.querySelector('[aria-label=Settings]').click()");
        await JsUntil(ui,"!![...document.querySelectorAll('[role=button]')].find(e=>e.textContent.trim()==='Appearance')");
        await ui.EvaluateAsync("[...document.querySelectorAll('[role=button]')].find(e=>e.textContent.trim()==='Appearance').click()");
        await JsUntil(ui,"!!document.querySelector('#history-density-settings-trigger')");
    }
    private static async Task SetHistoryDensity(LocalHtmlSurface ui,string value) {
        await OpenAppearance(ui);
        await Fill(ui,"history-density-settings",value,"change");
        await JsUntil(ui,"document.querySelector('#history-density-settings').value==="+JsonSerializer.Serialize(value));
        await ui.EvaluateAsync("document.querySelector('[aria-label=History]').click()");
        await JsUntil(ui,"document.querySelector('#history-list')?.dataset.density==="+JsonSerializer.Serialize(value));
    }
    private static async Task Ready(LocalHtmlSurface ui) { await Until(()=>ui.IsReady||ui.InitializationError is not null); Check(ui.IsReady,ui.InitializationError??"HTML UI did not load."); }
    private static Task Fill(LocalHtmlSurface ui,string id,string value,string evt="input") => ui.EvaluateAsync($"(()=>{{const e=document.getElementById({JsonSerializer.Serialize(id)});e.value={JsonSerializer.Serialize(value)};e.dispatchEvent(new Event('{evt}',{{bubbles:true}}));}})()");
    private static async Task JsUntil(LocalHtmlSurface ui,string predicate) { var end=DateTime.UtcNow.AddSeconds(30); while(await ui.EvaluateAsync(predicate)!="true"){if(DateTime.UtcNow>end)throw new TimeoutException("HTML condition: "+predicate);await Task.Delay(50);} }
    private static async Task Until(Func<bool> condition) {var end=DateTime.UtcNow.AddSeconds(30);while(!condition()){if(DateTime.UtcNow>end)throw new TimeoutException("HTML desktop operation timed out.");await Task.Delay(25);}}
    private static void Check(bool value,string error) {if(!value)throw new InvalidOperationException(error);}
}
